create schema if not exists ged;
create table if not exists ged.label_scan_event(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,label_print_history_id uuid null,print_job_id uuid null,template_code varchar(80),subject_type varchar(40) not null,subject_id uuid,control_number text,location_expected text,location_scanned text,scan_source varchar(40) not null default 'WEB',scan_status varchar(40) not null default 'VALID',validation_message text,scanned_payload text,scanned_by uuid,scanned_at timestamptz not null default now(),ip_address inet,user_agent text,reg_status char(1) not null default 'A');
create table if not exists ged.label_inventory_session(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,session_number varchar(40) not null,title text not null,expected_location text,status varchar(40) not null default 'OPEN',started_by uuid,started_at timestamptz not null default now(),finished_by uuid,finished_at timestamptz,notes text,reg_status char(1) not null default 'A');
create table if not exists ged.label_inventory_item(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,session_id uuid not null references ged.label_inventory_session(id),scan_event_id uuid references ged.label_scan_event(id),subject_type varchar(40) not null,subject_id uuid,control_number text,expected_location text,found_location text,status varchar(40) not null default 'FOUND',divergence_message text,scanned_by uuid,scanned_at timestamptz not null default now(),display_order integer not null default 0,reg_status char(1) not null default 'A');
create table if not exists ged.label_replacement_request(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,old_label_print_history_id uuid,old_template_code varchar(80),new_label_print_history_id uuid,subject_type varchar(40) not null,subject_id uuid,control_number text,reason text not null,status varchar(40) not null default 'REQUESTED',requested_by uuid,requested_at timestamptz not null default now(),approved_by uuid,approved_at timestamptz,completed_by uuid,completed_at timestamptz,reg_status char(1) not null default 'A');
create index if not exists ix_label_scan_event_tenant_subject on ged.label_scan_event(tenant_id,subject_type,subject_id,scanned_at desc); create index if not exists ix_label_scan_event_control on ged.label_scan_event(tenant_id,control_number,scanned_at desc); create unique index if not exists ux_label_inventory_session_tenant_number on ged.label_inventory_session(tenant_id,session_number); create index if not exists ix_label_inventory_session_status on ged.label_inventory_session(tenant_id,status,started_at desc); create index if not exists ix_label_inventory_item_session on ged.label_inventory_item(tenant_id,session_id,display_order); create index if not exists ix_label_replacement_request_subject on ged.label_replacement_request(tenant_id,subject_type,subject_id,requested_at desc);
